import React from 'react';
import { useNavigate, useParams } from "react-router-dom";
import { Box, IconButton, Typography } from "@mui/material";
import ArrowBackIosIcon from '@mui/icons-material/ArrowBackIos';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { formatPostDate } from '../blog/formatPostDate';


const EachBlog = ({ posts }) => {
    const navigate = useNavigate();
    const { slug } = useParams();
    const post = posts.find((candidate) => candidate.slug === slug);

    if (!post) {
        return (
            <div className="blogpostpage">
                <h1>Blog</h1>
                <Box sx={{ padding: "24px", maxWidth: "800px", margin: "0 auto" }}>
                    <Typography variant="h4" component="h2" gutterBottom>
                        Post not found
                    </Typography>
                    <Typography variant="body1" sx={{ marginBottom: "24px" }}>
                        The blog post you requested does not exist.
                    </Typography>
                    <button type="button" onClick={() => navigate("/blog")}>Back to Blog</button>
                </Box>
            </div>
        );
    }

    return (
        <div className="blogpostpage">
            <h1>Blog</h1>
            <Box sx={{ padding: "24px", maxWidth: "800px", margin: "0 auto" }}>
                <Box
                    variant="outlined"
                    onClick={() => navigate("/blog")}
                    sx={{
                        width : "120px",
                        display: "flex",
                        justifyContent: 'center',
                        marginBottom: "16px",
                        textTransform: "none",
                        alignItems: 'center',
                        fontWeight: 'bold',
                        padding: "5px",
                        backgroundColor: '#1e1e1e',
                        borderRadius: '10px',
                        boxShadow: '0px 4px 10px rgba(0, 0, 0, 0.5)',
                        '&:hover': {
                          backgroundColor: '#808080', // Slight color change on hover
                          color:'black',
                        },
                    }}
                >
                    <IconButton edge="end" sx={{ color: 'white' }}>
                        <ArrowBackIosIcon/>   
                    </IconButton>
                    Back to Blog
                </Box>

                {/* Blog title */}
                <Typography
                    variant="h4"
                    component="h2"
                    sx={{ textAlign: "center", marginBottom: "8px" }}
                >
                    {post.title}
                </Typography>

                {/* Date and read time */}
                <Typography
                    variant="body1"
                    sx={{ textAlign: "center", color: "gray", marginBottom: "24px" }}
                >
                    {formatPostDate(post.publishedAt)} • {post.readingTime} min read
                </Typography>

                {/* Blog content */}
                <Box sx={{ textAlign: "justify", lineHeight: "1.7" }}>
                    <ReactMarkdown remarkPlugins={[remarkGfm]}>
                        {post.content}
                    </ReactMarkdown>
                </Box>

            </Box>
        </div>
    );
};

export default EachBlog;
